        conversion = match.group(2) if match.group(2) else None
        format_spec = match.group(3) if match.group(3) else None

        if conversion:
            value = convert(value, conversion)
        if format_spec:
            value = format_value(value, format_spec)
        else:
            value = str(value)
        return value

